$ErrorActionPreference = "Stop"
if (-not (Test-Path "backend\src\jobs")) { Write-Host "Ejecuta este script desde la raiz del repo (carpeta Contratos)." -ForegroundColor Red; exit 1 }
$b = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "backend\src\utils\reporteMensualArrendamientos.js"), [Convert]::FromBase64String($b))
Write-Host "OK backend\src\utils\reporteMensualArrendamientos.js"
$b = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "backend\src\jobs\scheduler.js"), [Convert]::FromBase64String($b))
Write-Host "OK backend\src\jobs\scheduler.js"
$b = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) "backend\src\routes\jobs.js"), [Convert]::FromBase64String($b))
Write-Host "OK backend\src\routes\jobs.js"
Write-Host "Listo. Ahora: git add -A; git commit -m Reporte mensual de vencimientos de Arrendamientos; git push" -ForegroundColor Green
Write-Host "Al terminar el despliegue en Render, el primer reporte sale solo al arrancar el servicio (con copia a jair@fpt.com.mx)." -ForegroundColor Yellow